static void extractCpuArchBrandFromSpec(String text, HardwareInfo info) {
	Matcher matcher = Patterns.CPU_ARCH_BRAND_PATTERN.matcher(text);
	if (matcher.find()) {
		info.setCpuArchitecture(matcher.group(1));
		info.setCpuBrand(matcher.group(2).trim());
	} else {
		// 尝试简化匹配
		Pattern simplePattern = Pattern.compile("CPU[：:]?[^\\n]*?([A-Za-z0-9]+)\\(\\d+C");
		Matcher simpleMatcher = simplePattern.matcher(text);
		if (simpleMatcher.find()) {
			info.setCpuBrand(simpleMatcher.group(1));
		}
	}
}

/**
 * 根据 replace_models 中的单个值，解析并查询 conf_server_list 中的替代产品
 * 匹配优先级：material_code（纯数字 / 括号内 code）> 括号内 model > product_model 原始值
 * material_code 一旦命中记录即短路：只沿链查找，不再回落其余匹配
 * 非数字且无法解析为括号格式的，直接按 product_model 原始值精确匹配
 *
 * @param replaceValue replace_models 数组中的单个字符串值
 * @param depth 当前递归深度
 * @return 状态正常的替代服务器，找不到返回 null
 */
private ConfServerListTab resolveReplaceTarget(String replaceValue, int depth) {
    if (StringUtils.isBlank(replaceValue)) {
        return null;
    }

    // 1. 纯数字 = 物料编码，直接按 material_code 精确匹配（命中即短路）
    if (replaceValue.matches("\\d+")) {
        return pickOrFollowChain(findRowsByField("material_code", replaceValue), replaceValue, depth);
    }

    // 2. 尝试解析 product_model(material_code) 格式，同时支持中文括号（）和英文括号()
    String modelPart = null;
    String codePart = null;

    if (replaceValue.contains("（")) {
        int lastParen = replaceValue.lastIndexOf("（");
        int lastClose = replaceValue.lastIndexOf("）");
        modelPart = replaceValue.substring(0, lastParen);
        codePart = (lastClose > lastParen) ? replaceValue.substring(lastParen + 1, lastClose) : "";
    } else if (replaceValue.contains("(")) {
        int lastParen = replaceValue.lastIndexOf("(");
        int lastClose = replaceValue.lastIndexOf(")");
        modelPart = replaceValue.substring(0, lastParen);
        codePart = (lastClose > lastParen) ? replaceValue.substring(lastParen + 1, lastClose) : "";
    }

    // 2.1 括号内是数字物料编码，优先按 material_code 精确匹配；一旦命中（无论是否可用）即短路，
    //     不再回落尝试 model / product_model
    if (modelPart != null && StringUtils.isNotBlank(codePart) && codePart.matches("\\d+")) {
        List<ConfServerListTab> codeRows = findRowsByField("material_code", codePart);
        if (CollectionUtils.isNotEmpty(codeRows)) {
            return pickOrFollowChain(codeRows, codePart, depth);
        }
    }

    // 2.2 model 部分精确匹配 product_model
    if (modelPart != null && StringUtils.isNotBlank(modelPart)) {
        ConfServerListTab byModel = pickOrFollowChain(findRowsByField("product_model", modelPart), modelPart, depth);
        if (byModel != null) {
            return byModel;
        }
    }

    // 3. 最后按 product_model 精确匹配（用原始值，DB 中 product_model 存的就是中文括号）
    return pickOrFollowChain(findRowsByField("product_model", replaceValue), replaceValue, depth);
}
